import unittest
class TestSpace(unittest.TestCase):
    def test_run(self):
        out = run_student_code()

        # Check specific common errors
        if "my name is  Tim Tester" in out:
            self.fail("❌ Hay un espacio extra antes del nombre 'Tim Tester'. Recuerda que la coma añade un espacio automáticamente.")

        if "( beginner )" in out:
             self.fail("❌ Hay un espacio extra dentro del paréntesis de nivel.")

        if "2000 - 3000" in out:
             self.fail("❌ Hay espacios extra alrededor del guión de salario.")

        self.assertIn("my name is Tim Tester, I am 20 years old", out)
        self.assertIn("- python (beginner)", out)
        self.assertIn("salary of 2000-3000 euros", out)

import unittest
class TestArith(unittest.TestCase):
    def test_run(self):
        out = run_student_code()
        if "42" in out and "27 + 15 = 42" not in out:
            self.fail("❌ Debes imprimir la operación completa (ej: '27 + 15 = 42'), no solo el resultado.")

        self.assertIn("27 + 15 = 42", out)
        self.assertIn("27 / 15 = 1.8", out)
